/**
 * Icons exported from the Connie Figma (Vision Board) that are not part of Phosphor.
 * Source SVGs are the Figma MCP exports in the team prototype (public/figma), kept as drawn.
 * Figma paint variables (--fill-0, --stroke-0) are mapped to currentColor so CSS sets the color
 * from Connie tokens. Generated, do not edit by hand.
 */

type Props = {
  className?: string;
  size?: number;
  width?: number;
  height?: number;
};

function make(
  viewBox: string,
  w: number,
  h: number,
  inner: string,
  name: string,
) {
  const Icon = ({ className, size, width, height }: Props) => (
    <svg
      className={className}
      width={width ?? size ?? w}
      height={height ?? size ?? h}
      viewBox={viewBox}
      fill="none"
      aria-hidden
      focusable="false"
      dangerouslySetInnerHTML={{ __html: inner }}
    />
  );
  Icon.displayName = name;
  return Icon;
}

